{
  "application": "ppt-generation",
  "case_id": "case-paper-agentic-self-awareness",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "ML researchers and graduate students interested in LLM-based agents and planning systems",
    "tone": "technical, analytical, research-forward"
  },
  "brief": {
    "title": "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge",
    "one_liner": "KnowSelf introduces agentic knowledgeable self-awareness, enabling LLM agents to autonomously decide when to act directly, self-reflect, or consult external knowledge during planning tasks.",
    "goal": "The audience should understand the problem of indiscriminate knowledge injection in agent planning, how KnowSelf's three-situation framework (fast/slow/knowledgeable thinking) addresses it, and the empirical evidence showing KnowSelf outperforms strong baselines while using minimal external knowledge."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "KnowSelf: Agentic Knowledgeable Self-Awareness for LLM-Based Agents",
      "objective": "Cover slide with paper title, source reference (arxiv.org/abs/2504.03553), and key tagline about enabling agents to autonomously regulate knowledge utilization through situational self-awareness."
    },
    {
      "id": "problem-flood-irrigation",
      "title": "Current Agent Training Uses 'Flood Irrigation' — Indiscriminate Knowledge Injection Hurts Efficiency",
      "objective": "Present the core problem: existing approaches blindly inject gold trajectories, external feedback, and domain knowledge without considering situational needs. Contrast with human self-awareness in decision-making. Use a conceptual diagram or bullet-point comparison of three existing paradigms (trajectory imitation, trial-and-error, knowledge-augmented) and their limitations."
    },
    {
      "id": "three-thinking-modes",
      "title": "Three Situational Modes: Fast Thinking, Slow Thinking, and Knowledgeable Thinking",
      "objective": "Define the three cognitive situations that KnowSelf identifies. Show the decision criterion: fast thinking (direct correct action), slow thinking (correct after reflection), knowledgeable thinking (needs external knowledge). Use a flow diagram or decision tree visualization referencing the framework figure."
    },
    {
      "id": "knowself-framework",
      "title": "KnowSelf Framework: Data Construction → Two-Stage Training → Self-Aware Inference",
      "objective": "Walk through the three-step pipeline: (1) heuristic situation judgment to mark special tokens on self-explored trajectories, (2) SFT followed by RPO training, (3) inference with selective token generation triggering reflection or knowledge retrieval. Reference the framework figure (figure_3.jpg)."
    },
    {
      "id": "qualitative-examples",
      "title": "KnowSelf Correctly Heats a Mug and Places a Saltshaker Where Baselines Fail",
      "objective": "Show two qualitative task examples side-by-side: (a) 'put a hot mug in cabinet' where KnowSelf uses reflection to heat the mug while OpenAI-O1 fails, and (b) 'put a saltshaker in drawer' where KnowSelf applies knowledge to place the object while DeepSeek-R1 gets stuck. Reference figure_1.jpg."
    },
    {
      "id": "alfworld-results",
      "title": "KnowSelf Achieves 84.33% on ALFWorld with Llama-8B Using Only 15% Knowledge",
      "objective": "Present the main results table comparing KnowSelf against ReAct, Reflexion, ExpeL, ETO, KnowAgent, and WKM across GPT-4o, Llama-8B, and Gemma-2B backbones on six ALFWorld task types. Highlight that KnowSelf uses far less knowledge (15% and 26%) yet outperforms methods using 100% knowledge. Use a data table visualization."
    },
    {
      "id": "efficiency-and-scaling",
      "title": "Minimal Knowledge, Maximum Impact: KnowSelf's Efficiency Advantage Over Full-Knowledge Methods",
      "objective": "Emphasize the efficiency angle: KnowSelf uses only ~15-26% knowledge queries compared to 100% for KnowAgent/WKM/ExpeL, yet achieves the best overall scores. Show a comparative bar chart or highlight the Know% column against All accuracy. Discuss the scaling behavior across model sizes (Gemma-2B vs Llama-8B)."
    },
    {
      "id": "takeaways",
      "title": "Key Takeaways: Self-Awareness Is the Missing Piece in Agent Planning",
      "objective": "Summarize 5 key findings: (1) Indiscriminate knowledge injection is wasteful and suboptimal, (2) Agents can learn situational self-awareness via special tokens with lightweight heuristic labeling, (3) KnowSelf with Llama-8B outperforms strong baselines including GPT-4o ReAct (84.33% vs 76.12%) and GPT-4o ExpeL (79.85%), (4) Only 15-26% knowledge usage needed versus 100% for competing methods, (5) The paradigm generalizes across model scales — even Gemma-2B reaches 79.85% matching GPT-4o ExpeL."
    }
  ]
}

