            color: var(--text-primary);
            margin-bottom: 0.25rem;
        }

        .takeaway-text p {
            font-size: var(--small-size);
        }

        .closing-slide {
            text-align: center;
        }

        .closing-slide .slide-content {
            align-items: center;
        }

        .closing-quote {
            max-width: 700px;
            font-family: var(--font-display);
            font-size: clamp(1.2rem, 3vw, 2rem);
            color: var(--text-primary);
